-- The chart of accounts is for whoever keeps or checks the books. An owner or an accountant adds
-- and changes the company's own accounts; the locked ones (is_control) are written only by
-- app.seed_accounts below and are closed to every policy here.
CREATE POLICY accounts_select ON public.accounts FOR SELECT TO app_runtime
  USING (tenant_id = (SELECT app.tenant_id()) AND (SELECT app.tenant_role()) IN ('owner', 'accountant', 'auditor'));
